import{c as t,Z as l,Q as r,j as s,m as n,o as a}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"氓","description":"","frontmatter":{"title":"氓","author":"佚名","dynasty":"先秦"},"headers":[],"relativePath":"books/shici/shijing/4.md","filePath":"books/shici/shijing/4.md"}'),h={name:"books/shici/shijing/4.md"};function c(d,i,u,_,m,p){const e=l("PoemAuthor"),o=l("PoemNav");return r(),s("div",null,[i[0]||(i[0]=n('<h1 id="氓" tabindex="-1">氓 <a class="header-anchor" href="#氓" aria-label="Permalink to &quot;氓&quot;">​</a></h1><p><strong>《诗经·卫风》</strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>氓之蚩蚩，抱布贸丝。匪来贸丝，来即我谋。送子涉淇，至于顿丘。匪我愆期，子无良媒。将子无怒，秋以为期。 乘彼垝垣，以望复关。不见复关，泣涕涟涟。既见复关，载笑载言。尔卜尔筮，体无咎言。以尔车来，以我贿迁。 桑之未落，其叶沃若。于嗟鸠兮，无食桑葚！于嗟女兮，无与士耽！士之耽兮，犹可说也。女之耽兮，不可说也。 桑之落矣，其黄而陨。自我徂尔，三岁食贫。淇水汤汤，渐车帷裳。女也不爽，士贰其行。士也罔极，二三其德。 三岁为妇，靡室劳矣；夙兴夜寐，靡有朝矣。言既遂矣，至于暴矣。兄弟不知，咥其笑矣。静言思之，躬自悼矣。 及尔偕老，老使我怨。淇则有岸，隰则有泮。总角之宴，言笑晏晏。信誓旦旦，不思其反。反是不思，亦已焉哉！</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>氓：民，指诗中的男主人公</li><li>蚩蚩：敦厚的样子，一说笑嘻嘻的样子</li><li>布：古代货币</li><li>贸：交换</li><li>匪：非，不是</li><li>即：就，靠近</li><li>谋：商量婚事</li><li>涉：渡过</li><li>淇：淇水，卫国河流</li><li>愆期：拖延婚期</li><li>将：请，愿</li><li>垝垣：倒塌的墙</li><li>复关：地名，男子所居之地</li><li>载：又</li><li>卜筮：占卜</li><li>体：卦象</li><li>咎言：不吉利的话</li><li>贿：财物，指嫁妆</li><li>沃若：润泽的样子</li><li>于嗟：感叹词</li><li>耽：沉溺</li><li>说：同&quot;脱&quot;，解脱</li><li>陨：坠落</li><li>徂：往</li><li>汤汤：水势浩大的样子</li><li>渐：浸湿</li><li>帷裳：车旁的布幔</li><li>爽：差错</li><li>贰：不专一</li><li>罔极：没有准则</li><li>二三其德：三心二意</li><li>靡：无，不</li><li>夙兴夜寐：早起晚睡</li><li>遂：顺心</li><li>咥：大笑的样子</li><li>躬：自身</li><li>悼：悲伤</li><li>隰：低湿之地</li><li>泮：边界</li><li>总角：古代少年男女的发式，指少年时代</li><li>晏晏：和悦的样子</li><li>旦旦：诚恳的样子</li><li>反：变心</li><li>已：罢了，结束</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>那个男子笑嘻嘻，抱着布匹来换丝。其实不是真换丝，找我商量婚姻事。送你渡过淇水河，一直送到顿丘边。不是我要拖婚期，是你没有好媒人。请你不要生怒气，秋天到来作为婚期。 登上那倒塌的墙，遥望复关盼情郎。望不见那复关啊，眼泪簌簌往下淌。终于看见复关来，又说又笑心欢畅。你占卜来你问卦，卦象没有不吉利。用你的车子来接我，我带上嫁妆嫁给你。 桑树叶子未落时，缀满枝头绿萋萋。唉呀那些斑鸠呀，别把桑葚吃嘴里！唉呀年轻姑娘们，别对男人太沉迷！男人若是太沉迷，还能解脱抽身去。女人若是太沉迷，想要解脱无法离。 桑树叶子落下了，枯黄憔悴任飘零。自从嫁到你家来，多年吃苦受清贫。淇水滔滔送我归，溅湿车旁帷幔巾。女子行为无差错，男子行为却变心。男人反复无常性，三心二意坏德行。 多年媳妇熬成婆，家务劳苦全担下。早起晚睡不停歇，没有一天得闲暇。家业有成你顺心，对我粗暴又打骂。兄弟不知我苦衷，反而对我笑哈哈。静下心来细思量，独自伤神泪暗洒。 当年曾说共白头，如今到老使我怨。淇水再宽总有岸，沼泽再阔也有边。少年时代多欢乐，说说笑笑情意绵。海誓山盟犹在耳，不想你竟会变心。你既变心不再想，那就从此一刀断！</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>《氓》是《诗经·卫风》中的长篇叙事诗，是中国文学史上第一首长篇叙事诗，讲述了一位女子从恋爱、结婚到被弃的完整过程，是一首弃妇诗。全诗六章，以女子的口吻叙述，情感真挚动人。前两章回忆恋爱与成婚，中间两章以桑叶起兴，告诫女子不要沉溺于爱情，并叙述婚后生活的贫苦与男子的变心，最后两章写被弃后的悔恨与决绝。诗中运用比兴手法，以&quot;桑之未落&quot;&quot;桑之落矣&quot;比喻女子从青春到衰老的过程，极具艺术感染力。此诗深刻揭示了古代社会中男女地位的不平等，具有强烈的现实意义。</p>',10)),a(e,{name:"《诗经》",years:"西周初年至春秋中叶",desc:"中国最早的诗歌总集，收录了西周初年至春秋中叶（前11世纪至前6世纪）的诗歌305篇，分为“风”“雅”“颂”三部分。《诗经》内容丰富，反映了周代社会生活的方方面面，是中国现实主义文学的源头。",link:"/books/shici/shijing","is-shijing":""}),a(o)])}const f=t(h,[["render",c]]);export{b as __pageData,f as default};
